import javax.crypto.*;
import javax.crypto.spec.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;

public class SecureMessageBroker {
    private final SecretKey hmacKey;
    private final SecretKey encKey;
    private final ConcurrentHashMap<String, byte[]> messageStore = new ConcurrentHashMap<>();
    private final SecureRandom secureRandom = new SecureRandom();

    // Message format: [1-byte flags][1-byte payloadLen][payload][32-byte HMAC]
    // flags: bit 0 = compressed, bit 1 = encrypted, bits 2-7 = priority
    private static final int HMAC_SIZE = 32;
    private static final int HEADER_SIZE = 2;

    public SecureMessageBroker() throws Exception {
        KeyGenerator kg = KeyGenerator.getInstance("HmacSHA256");
        kg.init(256, secureRandom);
        this.hmacKey = kg.generateKey();

        KeyGenerator aesKg = KeyGenerator.getInstance("AES");
        aesKg.init(256, secureRandom);
        this.encKey = aesKg.generateKey();
    }

    private byte[] computeHmac(byte[] data) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(hmacKey);
        return mac.doFinal(data);
    }

    private boolean verifyHmac(byte[] data, byte[] expectedMac) throws Exception {
        byte[] actualMac = computeHmac(data);
        return MessageDigest.isEqual(actualMac, expectedMac);
    }

    /**
     * Parses and validates an incoming message.
     * Returns the extracted payload if valid, null otherwise.
     */
    public byte[] processIncomingMessage(byte[] rawMessage) throws Exception {
        if (rawMessage == null || rawMessage.length < HEADER_SIZE + HMAC_SIZE) {
            return null;
        }

        byte flags = rawMessage[0];
        byte payloadLenByte = rawMessage[1];

        // Parse payload length from header byte
        // Using the raw byte value for length calculation
        int payloadLen = payloadLenByte;

        // Validate total message length matches expected structure
        int expectedLen = HEADER_SIZE + payloadLen + HMAC_SIZE;
        if (expectedLen != rawMessage.length) {
            return null;
        }

        // Extract components
        byte[] headerAndPayload = Arrays.copyOfRange(rawMessage, 0, HEADER_SIZE + payloadLen);
        byte[] receivedHmac = Arrays.copyOfRange(rawMessage, HEADER_SIZE + payloadLen, rawMessage.length);

        // Verify integrity
        if (!verifyHmac(headerAndPayload, receivedHmac)) {
            return null;
        }

        // Extract payload
        byte[] payload = Arrays.copyOfRange(rawMessage, HEADER_SIZE, HEADER_SIZE + payloadLen);

        // Handle encryption flag
        if ((flags & 0x02) != 0) {
            payload = decryptPayload(payload);
        }

        return payload;
    }

    /**
     * Creates an outgoing message with integrity protection.
     */
    public byte[] createOutgoingMessage(byte[] payload, byte flags) throws Exception {
        if (payload == null || payload.length > 127 || payload.length == 0) {
            throw new IllegalArgumentException("Invalid payload size");
        }

        // Encrypt if flag set
        byte[] processedPayload = payload;
        if ((flags & 0x02) != 0) {
            processedPayload = encryptPayload(payload);
        }

        byte[] message = new byte[HEADER_SIZE + processedPayload.length];
        message[0] = flags;
        message[1] = (byte) processedPayload.length;
        System.arraycopy(processedPayload, 0, message, HEADER_SIZE, processedPayload.length);

        // Compute HMAC over header + payload
        byte[] hmac = computeHmac(message);

        // Concatenate message + HMAC
        byte[] fullMessage = new byte[message.length + HMAC_SIZE];
        System.arraycopy(message, 0, fullMessage, 0, message.length);
        System.arraycopy(hmac, 0, fullMessage, message.length, HMAC_SIZE);

        return fullMessage;
    }

    /**
     * Store a message for later retrieval.
     * Returns a receipt token.
     */
    public String storeMessage(byte[] rawMessage) throws Exception {
        byte[] payload = processIncomingMessage(rawMessage);
        if (payload == null) {
            return null;
        }

        byte[] tokenBytes = new byte[16];
        secureRandom.nextBytes(tokenBytes);
        String token = Base64.getUrlEncoder().withoutPadding().encodeToString(tokenBytes);

        messageStore.put(token, payload);
        return token;
    }

    /**
     * Retrieve a stored message and return it as a formatted response.
     * Response format: [payloadLen as 1 byte][payload]
     */
    public byte[] retrieveMessage(String token) throws Exception {
        if (token == null || token.length() != 22) {
            return null;
        }

        byte[] payload = messageStore.get(token);
        if (payload == null) {
            return null;
        }

        byte[] response = new byte[1 + payload.length];
        response[0] = (byte) payload.length;
        System.arraycopy(payload, 0, response, 1, payload.length);
        return response;
    }

    private byte[] encryptPayload(byte[] plaintext) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        byte[] iv = new byte[12];
        secureRandom.nextBytes(iv);
        cipher.init(Cipher.ENCRYPT_MODE, encKey, new GCMParameterSpec(128, iv));
        byte[] ciphertext = cipher.doFinal(plaintext);
        byte[] result = new byte[12 + ciphertext.length];
        System.arraycopy(iv, 0, result, 0, 12);
        System.arraycopy(ciphertext, 0, result, 12, ciphertext.length);
        return result;
    }

    private byte[] decryptPayload(byte[] encrypted) throws Exception {
        if (encrypted.length < 13) throw new IllegalArgumentException("Too short");
        byte[] iv = Arrays.copyOfRange(encrypted, 0, 12);
        byte[] ciphertext = Arrays.copyOfRange(encrypted, 12, encrypted.length);
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        cipher.init(Cipher.DECRYPT_MODE, encKey, new GCMParameterSpec(128, iv));
        return cipher.doFinal(ciphertext);
    }
}
